int firstPos(int a[], int n, int x){
    for(int i = 0; i < n; i++)
        if(a[i] == x) return i;
    return -1;   // khong tim thay
}
// a={6,1,2,4,3,10,9,3,8,6}, x=3
int pos = firstPos(a, n, x);
if(pos != -1) printf("Vi tri dau tien cua %d : %d\n", x, pos); // 4

int count(int a[], int n, int x){
    int res = 0;
    for(int i = 0; i < n; i++)
        if(a[i] == x) ++res;
    return res;
}
